using System.Reflection;
using System.Text.Json;
using HarmonyLib;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.Models;

namespace CombatSolver;
internal sealed partial class UnattendedTestRunner
{
    private Task AssertNativeGenerationCallbackProofAsync(CombatState live, Player player)
    {
        var entries = Harmony.GetAllPatchedMethods()
            .Where(method => method.Module.Assembly == typeof(CardModel).Assembly)
            .OrderBy(method => method.DeclaringType!.FullName).ThenBy(method=>method.Name)
            .Select(method => new {
                target = method.ToString(), type = method.DeclaringType!.FullName,
                model = typeof(AbstractModel).IsAssignableFrom(method.DeclaringType),
                command = method.DeclaringType!.Namespace?.StartsWith("MegaCrit.Sts2.Core.Commands",StringComparison.Ordinal)==true,
                patches = DescribePatches(Harmony.GetPatchInfo(method)!)
            }).ToArray();
        Directory.CreateDirectory(_request.EvidenceDirectory);
        File.WriteAllText(Path.Combine(_request.EvidenceDirectory,"native-gameplay-patches.json"),
            JsonSerializer.Serialize(entries,new JsonSerializerOptions{WriteIndented=true}));
        Entry.Logger.Info($"NATIVE_GENERATION_CALLBACK_PROOF_PATCH_TARGETS count={entries.Length}");
        return Task.CompletedTask;
    }
    private static object[] DescribePatches(Patches patches)
        => patches.Prefixes.Select(p=>Describe(p,"prefix"))
            .Concat(patches.Postfixes.Select(p=>Describe(p,"postfix")))
            .Concat(patches.Transpilers.Select(p=>Describe(p,"transpiler")))
            .Concat(patches.Finalizers.Select(p=>Describe(p,"finalizer"))).ToArray();
    private static object Describe(Patch p,string kind)
        => new {kind,p.owner,handler=p.PatchMethod.ToString(),type=p.PatchMethod.DeclaringType?.FullName,
            assembly=p.PatchMethod.Module.Assembly.GetName().Name,mvid=p.PatchMethod.Module.ModuleVersionId};
}

