using System.Collections;
using System.Reflection;
using System.Text.Json;
using CombatSolver.Engine.Common;
using HarmonyLib;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Commands;
using MegaCrit.Sts2.Core.Entities.Creatures;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.GameActions.Multiplayer;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Powers;
using STS2RitsuLib.Combat.Healing;

namespace CombatSolver;
internal sealed partial class UnattendedTestRunner
{
    private sealed class UnknownGlobalHealListener : IHealHookListener
    {
        public int Calls;
        public decimal ModifyHealMultiplicative(HealContext context, decimal amount)
        { Calls++; return 2m; }
    }
    private async Task AssertNativeGenerationCallbackProofAsync(CombatState live, Player player)
    {
        foreach (var relic in player.Relics.ToArray()) await RelicCmd.Remove(relic);
        foreach (var power in live.Creatures.SelectMany(c=>c.Powers).ToArray()) await PowerCmd.Remove(power);
        await ClearPlayerPilesAsync(player);
        await InjectCardAsync(live, player, new(){CardId="DEFEND_REGENT",Pile="Hand",TreatAsDeckCard=true});
        foreach (var potion in player.PotionSlots.ToArray()) potion?.Discard();
        await CreatureCmd.SetCurrentHp(player.Creature,35);
        await PowerCmd.Apply<RegenPower>(new ThrowingPlayerChoiceContext(),player.Creature,5,player.Creature,null);
        var clean=CombatRootSnapshot.Capture(live);
        int cleanBound=StrategicHpRecoveryBound.ComponentHealingUpperBound(clean.ForkSimulator(),player,0);
        if (!clean.UsesComponentHealingCertificate || cleanBound!=15)
            throw new InvalidOperationException($"Clean fixture: {clean.ComponentHealingRejection}, {cleanBound}");
        object registry=typeof(HealHook).GetField("GlobalListeners",BindingFlags.Static|BindingFlags.NonPublic)!.GetValue(null)!;
        FieldInfo values=registry.GetType().GetField("_snapshot",BindingFlags.Instance|BindingFlags.NonPublic)!;
        Array initial=(Array)values.GetValue(registry)!;
        if(initial.Length!=0)throw new InvalidOperationException("Existing global heal listeners: refusing to replace them.");
        var listener=new UnknownGlobalHealListener();
        HealHook.RegisterGlobalListener(listener);
        try
        {
            var admitted=CombatRootSnapshot.Capture(live);
            var simulator=admitted.ForkSimulator();var state=(SimulatedCombatState)simulator.State.CombatState;
            int unknownBound=StrategicHpRecoveryBound.ComponentHealingUpperBound(simulator,player,0);
            if(!admitted.UsesComponentHealingCertificate || unknownBound!=15
                ||state.RootRunModSubscriberCount!=0 ||state.RootCombatModSubscriberCount!=0)
                throw new InvalidOperationException("Expected unknown global-hook admission did not reproduce.");
            var power=player.Creature.Powers.Single(p=>p is RegenPower);
            MethodInfo callback=typeof(RegenPower).GetMethod("BeforeSideTurnEndEarly",BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic)!;
            object?[] arguments=callback.GetParameters().Select(parameter=>
                parameter.ParameterType==typeof(PlayerChoiceContext)?(object)new ThrowingPlayerChoiceContext():
                parameter.ParameterType==typeof(CombatSide)?CombatSide.Player:
                parameter.ParameterType==typeof(IEnumerable<Creature>)?(object)new Creature[]{player.Creature}:
                throw new InvalidOperationException("Unknown Regen callback parameter: "+parameter)).ToArray();
            int before=player.Creature.CurrentHp;
            for(int i=0;i<5;i++)await ((Task)callback.Invoke(power,arguments)!);
            int gain=player.Creature.CurrentHp-before;
            if(gain!=30 || listener.Calls!=5)throw new InvalidOperationException($"Native modified Regen: gain{gain}, calls{listener.Calls}");
            string directory=_request.EvidenceDirectory??throw new InvalidOperationException("Missing evidence directory.");
            Directory.CreateDirectory(directory);
            File.WriteAllText(Path.Combine(directory,"global-heal-counterexample.json"),JsonSerializer.Serialize(new{
                cleanBound,unknownBound,nativeRegenerationGain=gain,nativeCalls=listener.Calls,
                rootRunModSubscribers=state.RootRunModSubscriberCount,rootCombatModSubscribers=state.RootCombatModSubscriberCount,
                callback=callback.ToString(),before,after=player.Creature.CurrentHp,
                scope="Five isolated real RegenPower callbacks; not a complete native battle or a measured false prune."},new JsonSerializerOptions{WriteIndented=true}));
            _completedChecks.Add("GlobalHealCounterexample:UnknownListenerAdmitted:Bound15:NativeRegen30:NoModSubscribers");
        }
        finally
        {
            ((IList)registry.GetType().GetField("_listeners",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(registry)!).Remove(listener);
            values.SetValue(registry,initial);
        }
    }
}

