using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using MegaCrit.Sts2.Core.Models;

namespace STS2RitsuLib.Models.Capabilities;

internal static class ModelCapabilityDefaults
{
	private readonly record struct ModelDefaultCapabilityModifierEntry(string ModId, string ModifierId, Type OwnerType, int Order, long RegistrationOrder, Action<AbstractModel, ModelCapabilityList> Modify);

	private static readonly Lock SyncRoot = new Lock();

	private static readonly List<ModelDefaultCapabilityModifierEntry> Modifiers = new List<ModelDefaultCapabilityModifierEntry>();

	private static Dictionary<Type, ModelDefaultCapabilityModifierEntry[]> _modifiersByOwnerType = new Dictionary<Type, ModelDefaultCapabilityModifierEntry[]>();

	private static long _nextOrder;

	public static void Modify<TModel>(string modId, string modifierId, Action<TModel, ModelCapabilityList> modifier, int order = 0) where TModel : AbstractModel
	{
		ArgumentNullException.ThrowIfNull(modifier, "modifier");
		Modify(modId, modifierId, typeof(TModel), delegate(AbstractModel model, ModelCapabilityList capabilities)
		{
			modifier((TModel)(object)model, capabilities);
		}, order);
	}

	public static void Modify(string modId, string modifierId, Type ownerType, Action<AbstractModel, ModelCapabilityList> modifier, int order = 0)
	{
		ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
		ArgumentException.ThrowIfNullOrWhiteSpace(modifierId, "modifierId");
		ArgumentNullException.ThrowIfNull(ownerType, "ownerType");
		ArgumentNullException.ThrowIfNull(modifier, "modifier");
		if (ownerType.ContainsGenericParameters || ownerType.IsInterface || !typeof(AbstractModel).IsAssignableFrom(ownerType))
		{
			throw new ArgumentException("Type '" + ownerType.FullName + "' must be an abstract model type or a concrete model type.", "ownerType");
		}
		using (SyncRoot.EnterScope())
		{
			if (Modifiers.Any((ModelDefaultCapabilityModifierEntry entry) => string.Equals(entry.ModId, modId, StringComparison.OrdinalIgnoreCase) && string.Equals(entry.ModifierId, modifierId, StringComparison.Ordinal)))
			{
				throw new InvalidOperationException("Default capability modifier is already registered: " + modId + "/" + modifierId);
			}
			Modifiers.Add(new ModelDefaultCapabilityModifierEntry(modId, modifierId, ownerType, order, _nextOrder++, modifier));
			Volatile.Write(ref _modifiersByOwnerType, new Dictionary<Type, ModelDefaultCapabilityModifierEntry[]>());
		}
		ModelCapabilityHookListeners.InvalidateDefaultCapabilitySourceCache();
	}

	internal static bool HasDefaultCapabilitySource(AbstractModel owner)
	{
		ArgumentNullException.ThrowIfNull(owner, "owner");
		if (owner is IModelCapabilitySource)
		{
			return true;
		}
		return GetModifiers(((object)owner).GetType()).Length != 0;
	}

	internal static IReadOnlyList<IModelCapability> Create(AbstractModel owner)
	{
		ArgumentNullException.ThrowIfNull(owner, "owner");
		ModelCapabilityList modelCapabilityList = new ModelCapabilityList();
		if (owner is IModelCapabilitySource provider)
		{
			RunProvider(provider, modelCapabilityList);
		}
		ModelDefaultCapabilityModifierEntry[] modifiers = GetModifiers(owner);
		foreach (ModelDefaultCapabilityModifierEntry modifier in modifiers)
		{
			RunModifier(owner, modifier, modelCapabilityList);
		}
		return modelCapabilityList.ToArray();
	}

	private static ModelDefaultCapabilityModifierEntry[] GetModifiers(AbstractModel owner)
	{
		return GetModifiers(((object)owner).GetType());
	}

	private static ModelDefaultCapabilityModifierEntry[] GetModifiers(Type ownerType)
	{
		Dictionary<Type, ModelDefaultCapabilityModifierEntry[]> dictionary = Volatile.Read(in _modifiersByOwnerType);
		if (dictionary.TryGetValue(ownerType, out var value))
		{
			return value;
		}
		using (SyncRoot.EnterScope())
		{
			dictionary = Volatile.Read(in _modifiersByOwnerType);
			if (dictionary.TryGetValue(ownerType, out value))
			{
				return value;
			}
			value = (from entry in Modifiers
				where entry.OwnerType.IsAssignableFrom(ownerType)
				orderby entry.Order, entry.RegistrationOrder
				select entry).ToArray();
			Dictionary<Type, ModelDefaultCapabilityModifierEntry[]> value2 = new Dictionary<Type, ModelDefaultCapabilityModifierEntry[]>(dictionary) { [ownerType] = value };
			Volatile.Write(ref _modifiersByOwnerType, value2);
			return value;
		}
	}

	private static void RunProvider(IModelCapabilitySource provider, ModelCapabilityList capabilities)
	{
		IModelCapability[] capabilities2 = capabilities.ToArray();
		try
		{
			provider.BuildDefaultCapabilities(capabilities);
		}
		catch
		{
			capabilities.Restore(capabilities2);
			throw;
		}
	}

	private static void RunModifier(AbstractModel owner, ModelDefaultCapabilityModifierEntry modifier, ModelCapabilityList capabilities)
	{
		IModelCapability[] capabilities2 = capabilities.ToArray();
		try
		{
			modifier.Modify(owner, capabilities);
		}
		catch
		{
			capabilities.Restore(capabilities2);
			throw;
		}
	}
}
