using System;
using System.Collections.Generic;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Runs;

namespace STS2RitsuLib.Models.Capabilities;

/// <summary>
///     <para xml:lang="en">Shared dispatcher for model- and capability-backed hook listener streams.</para>
///     <para xml:lang="zh-CN">由模型和能力提供的钩子监听器流所共用的分发器。</para>
/// </summary>
public static class ModelHookListenerDispatcher
{
	/// <summary>
	///     <para xml:lang="en">Resolves listeners from combat hook models, attached capabilities, and optional extra models.</para>
	///     <para xml:lang="zh-CN">从战斗钩子模型、已附加能力与可选的额外模型中解析监听器。</para>
	/// </summary>
	public static IEnumerable<ModelHookListener<TListener>> FromCombat<TListener>(ICombatState combatState, params AbstractModel?[] extraModels) where TListener : class
	{
		ArgumentNullException.ThrowIfNull(combatState, "combatState");
		ArgumentNullException.ThrowIfNull(extraModels, "extraModels");
		return FromModelsCore<TListener>(combatState.IterateHookListeners(), null, null, extraModels);
	}

	internal static IEnumerable<ModelHookListener<TListener>> FromCombat<TListener>(ICombatState combatState, ModelHookListenerRegistry<TListener> globalListeners, params AbstractModel?[] extraModels) where TListener : class
	{
		return FromModelsCore(combatState.IterateHookListeners(), globalListeners, null, extraModels);
	}

	/// <summary>
	///     <para xml:lang="en">
	///         Resolves combat listeners and inserts an optional adapter immediately after each source model or
	///         model-backed capability for which <paramref name="adapterResolver" /> returns one.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         解析战斗监听器；当 <paramref name="adapterResolver" /> 为来源模型或由模型承载的能力返回适配器时，
	///         将该适配器紧接在对应来源之后插入。
	///     </para>
	/// </summary>
	public static IEnumerable<ModelHookListener<TListener>> FromCombatWithAdapters<TListener>(ICombatState combatState, Func<AbstractModel, TListener?> adapterResolver, params AbstractModel?[] extraModels) where TListener : class
	{
		ArgumentNullException.ThrowIfNull(combatState, "combatState");
		ArgumentNullException.ThrowIfNull(adapterResolver, "adapterResolver");
		ArgumentNullException.ThrowIfNull(extraModels, "extraModels");
		return FromModelsCore(combatState.IterateHookListeners(), null, adapterResolver, extraModels);
	}

	internal static IEnumerable<ModelHookListener<TListener>> FromCombatWithAdapters<TListener>(ICombatState combatState, ModelHookListenerRegistry<TListener> globalListeners, Func<AbstractModel, TListener?> adapterResolver, params AbstractModel?[] extraModels) where TListener : class
	{
		ArgumentNullException.ThrowIfNull(adapterResolver, "adapterResolver");
		return FromModelsCore(combatState.IterateHookListeners(), globalListeners, adapterResolver, extraModels);
	}

	/// <summary>
	///     <para xml:lang="en">Resolves listeners from run hook models, attached capabilities, and optional extra models.</para>
	///     <para xml:lang="zh-CN">从局内钩子模型、已附加能力与可选的额外模型中解析监听器。</para>
	/// </summary>
	public static IEnumerable<ModelHookListener<TListener>> FromRun<TListener>(IRunState runState, ICombatState? combatState, params AbstractModel?[] extraModels) where TListener : class
	{
		ArgumentNullException.ThrowIfNull(runState, "runState");
		ArgumentNullException.ThrowIfNull(extraModels, "extraModels");
		return FromModelsCore<TListener>(runState.IterateHookListeners(combatState), null, null, extraModels);
	}

	internal static IEnumerable<ModelHookListener<TListener>> FromRun<TListener>(IRunState runState, ICombatState? combatState, ModelHookListenerRegistry<TListener> globalListeners, params AbstractModel?[] extraModels) where TListener : class
	{
		return FromModels(runState.IterateHookListeners(combatState), globalListeners, extraModels);
	}

	/// <summary>
	///     <para xml:lang="en">
	///         Resolves listeners from an explicit model sequence, attached capabilities, and optional extra
	///         models.
	///     </para>
	///     <para xml:lang="zh-CN">从显式模型序列、已附加能力与可选的额外模型中解析监听器。</para>
	/// </summary>
	public static IEnumerable<ModelHookListener<TListener>> FromModels<TListener>(IEnumerable<AbstractModel> models, params AbstractModel?[] extraModels) where TListener : class
	{
		ArgumentNullException.ThrowIfNull(models, "models");
		ArgumentNullException.ThrowIfNull(extraModels, "extraModels");
		return FromModelsCore<TListener>(models, null, null, extraModels);
	}

	internal static IEnumerable<ModelHookListener<TListener>> FromModels<TListener>(IEnumerable<AbstractModel> models, ModelHookListenerRegistry<TListener> globalListeners, params AbstractModel?[] extraModels) where TListener : class
	{
		return FromModelsCore(models, globalListeners, null, extraModels);
	}

	private static IEnumerable<ModelHookListener<TListener>> FromModelsCore<TListener>(IEnumerable<AbstractModel> models, ModelHookListenerRegistry<TListener>? globalListeners, Func<AbstractModel, TListener?>? adapterResolver, params AbstractModel?[] extraModels) where TListener : class
	{
		HashSet<TListener> seen = new HashSet<TListener>(ReferenceEqualityComparer.Instance);
		HashSet<AbstractModel> adaptedModels = null;
		foreach (AbstractModel model in models)
		{
			if (model is TListener val && seen.Add(val))
			{
				yield return new ModelHookListener<TListener>(val, model);
			}
			if (TryResolveAdapter(model, out var adapter))
			{
				yield return new ModelHookListener<TListener>(adapter, model);
			}
			if (!ModelCapabilities.TryGet(model, out ModelCapabilitySet collection) || collection.Count == 0)
			{
				continue;
			}
			IModelCapability[] attachedSnapshot = collection.GetAttachedSnapshot();
			IModelCapability[] array = attachedSnapshot;
			foreach (IModelCapability capability in array)
			{
				if (capability.Owner == model)
				{
					if (capability is TListener val2 && seen.Add(val2))
					{
						yield return new ModelHookListener<TListener>(val2, (AbstractModel?)((capability is AbstractModel) ? capability : null));
					}
					AbstractModel val3 = (AbstractModel)((capability is AbstractModel) ? capability : null);
					if (val3 != null && TryResolveAdapter(val3, out adapter))
					{
						yield return new ModelHookListener<TListener>(adapter, val3);
					}
				}
			}
		}
		foreach (AbstractModel model in extraModels)
		{
			AbstractModel val4 = model;
			if (val4 == null)
			{
				continue;
			}
			if (val4 is TListener val5 && seen.Add(val5))
			{
				yield return new ModelHookListener<TListener>(val5, model);
			}
			if (TryResolveAdapter(model, out var adapter2))
			{
				yield return new ModelHookListener<TListener>(adapter2, model);
			}
			if (!ModelCapabilities.TryGet(model, out ModelCapabilitySet collection2) || collection2.Count == 0)
			{
				continue;
			}
			IModelCapability[] attachedSnapshot2 = collection2.GetAttachedSnapshot();
			IModelCapability[] array = attachedSnapshot2;
			foreach (IModelCapability capability in array)
			{
				if (capability.Owner == model)
				{
					if (capability is TListener val6 && seen.Add(val6))
					{
						yield return new ModelHookListener<TListener>(val6, (AbstractModel?)((capability is AbstractModel) ? capability : null));
					}
					AbstractModel val7 = (AbstractModel)((capability is AbstractModel) ? capability : null);
					if (val7 != null && TryResolveAdapter(val7, out adapter2))
					{
						yield return new ModelHookListener<TListener>(adapter2, val7);
					}
				}
			}
		}
		if (globalListeners == null)
		{
			yield break;
		}
		TListener[] array2 = globalListeners.Snapshot();
		foreach (TListener val8 in array2)
		{
			if (seen.Add(val8))
			{
				yield return new ModelHookListener<TListener>(val8, null);
			}
		}
		bool TryResolveAdapter(AbstractModel val9, out TListener reference)
		{
			reference = null;
			if (adapterResolver != null)
			{
				HashSet<AbstractModel> hashSet = adaptedModels;
				if (hashSet == null || !hashSet.Contains(val9))
				{
					TListener val10 = adapterResolver(val9);
					if (val10 == null)
					{
						return false;
					}
					if (adaptedModels == null)
					{
						adaptedModels = new HashSet<AbstractModel>(ReferenceEqualityComparer.Instance);
					}
					adaptedModels.Add(val9);
					if (!seen.Add(val10))
					{
						return false;
					}
					reference = val10;
					return true;
				}
			}
			return false;
		}
	}
}
