using System;
using System.Collections.Generic;
using System.Threading;

namespace STS2RitsuLib.Models.Capabilities;

/// <summary>
///     <para xml:lang="en">Thread-safe process-wide hook listener registry.</para>
///     <para xml:lang="zh-CN">线程安全的进程级钩子监听器注册表。</para>
/// </summary>
internal sealed class ModelHookListenerRegistry<TListener> where TListener : class
{
	private readonly List<TListener> _listeners = new List<TListener>();

	private readonly Lock _syncRoot = new Lock();

	private TListener[] _snapshot = Array.Empty<TListener>();

	internal void Register(TListener listener)
	{
		ArgumentNullException.ThrowIfNull(listener, "listener");
		using (_syncRoot.EnterScope())
		{
			if (!_listeners.Contains(listener))
			{
				_listeners.Add(listener);
				Volatile.Write(ref _snapshot, _listeners.ToArray());
			}
		}
	}

	internal TListener[] Snapshot()
	{
		return Volatile.Read(in _snapshot);
	}
}
