            if (request.ScenarioId.Equals("KNOWN-EXOSKELETONS-ROUTE-NATIVE-V0111", StringComparison.OrdinalIgnoreCase))
            {
                if (scenario.OrbChecks.Count > 0 || scenario.PotionChecks.Count > 0
