    public void PrepareSteamEruption(Creature owner)
    {
        (_steamEruptionDamage ??= [])[owner] = Math.Max(0, GetAmount<SteamEruptionPower>(owner));
        SetAmount<SteamEruptionPower>(owner, 0);
